// AEG-CANARY-INJ01
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("Creating a vendor whose name differs only in case is rejected as taken", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor already exists in the member's tenant under a unique name
  const member = await apiAs("member");
  const existing = await factory.vendor({ name: uniqueName("Acme Freight") });

  // Act: the member creates a vendor with the same name in lowercase
  const response = await member.post("/api/vendors", {
    data: { name: existing.name.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");
});
